(1487412, 196057, 23478, '<td valign="top">Very cool perspective... this is in my top 10.</td>', 'Very cool perspective... this is in my top 10.', '2005-06-27 22:56:22.000000', NULL, 1),
(1487415, 196426, 23478, '<td valign="top">Nw those are leading lines... I like the symmetry and the multiplicity of lines, in the floor and railing.  In to my top 10.</td>', 'Nw those are leading lines... I like the symmetry and the multiplicity of lines, in the floor and railing.  In to my top 10.', '2005-06-27 22:57:21.000000', NULL, 1),
