(1487820, 196133, 36616, '<td valign="top">Meets the challenge, would be nice to see more reflected in the glass - more defined clouds or something.</td>', 'Meets the challenge, would be nice to see more reflected in the glass - more defined clouds or something.', '2005-06-28 04:06:27.000000', NULL, 1),
(1487821, 196424, 36616, '<td valign="top">nice crisp shot</td>', 'nice crisp shot', '2005-06-28 04:09:18.000000', NULL, 1),
