(1487831, 195531, 31443, '<td valign="top">Strange to see only the fingers of the hand in clear focus, a good study though..</td>', 'Strange to see only the fingers of the hand in clear focus, a good study though..', '2005-06-28 04:24:41.000000', NULL, 1),
(1487833, 196011, 36616, '<td valign="top">I am led to the doorway but then distracted by the dome. Makes for less overall impact for me.</td>', 'I am led to the doorway but then distracted by the dome. Makes for less overall impact for me.', '2005-06-28 04:27:55.000000', NULL, 1),
(1487834, 195944, 31443, '<td valign="top">This image has the feeling of "underwater" about it, beautiful face and splendid head cover</td>', 'This image has the feeling of "underwater" about it, beautiful face and splendid head cover', '2005-06-28 04:29:11.000000', NULL, 1),
