(1494951, 194252, 29154, '<td valign="top">Wonderful composition ! I just think it''s a little overprocessed, but still very nice.</td>', 'Wonderful composition ! I just think it''s a little overprocessed, but still very nice.', '2005-06-30 12:41:01.000000', NULL, 1),
(1494963, 195829, 29154, '<td valign="top">I like it a lot. Very well done.</td>', 'I like it a lot. Very well done.', '2005-06-30 12:44:03.000000', NULL, 1),
