(1496116, 196426, 12962, '<td valign="top">What a beautiful story-telling photograph.    Impressive lighting you''ve captured here.</td>', 'What a beautiful story-telling photograph.    Impressive lighting you''ve captured here.', '2005-06-30 20:54:35.000000', NULL, 1),
(1496173, 196161, 10818, '<td valign="top">Interesting photo, great lines and color.  Wish it was a bit crisper, but very ncie.</td>', 'Interesting photo, great lines and color.  Wish it was a bit crisper, but very ncie.', '2005-06-30 21:17:09.000000', NULL, 1),
(1496182, 195511, 10818, '<td valign="top">Beautiful bike, very elegant bike shot.  The trash can is a tad intrusive...but overall well done, interesting perspective photo.</td>', 'Beautiful bike, very elegant bike shot.  The trash can is a tad intrusive...but overall well done, interesting perspective photo.', '2005-06-30 21:20:25.000000', NULL, 1),
(1496189, 196058, 10818, '<td valign="top">Very good lighting and crispness.</td>', 'Very good lighting and crispness.', '2005-06-30 21:25:31.000000', NULL, 1),
(1496194, 196364, 13026, '<td valign="top">Is this our Mr. Zoom?<br/>Love the reflections!</td>', 'Is this our Mr. Zoom?Love the reflections!', '2005-06-30 21:28:24.000000', NULL, 1),
(1496240, 193124, 15305, '<td valign="top">Magnificent picture!!! Congratulations</td>', 'Magnificent picture!!! Congratulations', '2005-06-30 22:04:22.000000', NULL, 1),
(1496254, 195597, 15305, '<td valign="top">I hope your camera survived!!!</td>', 'I hope your camera survived!!!', '2005-06-30 22:14:01.000000', NULL, 1),
(1496258, 196208, 39144, '<td valign="top">I like the composition, but I think the DOF is lacking with the foreground being out of focus.</td>', 'I like the composition, but I think the DOF is lacking with the foreground being out of focus.', '2005-06-30 22:17:08.000000', NULL, 1),
