(1498148, 194202, 29557, '<td valign="top">quite artsy.. i think i would have kept the purple colorless.</td>', 'quite artsy.. i think i would have kept the purple colorless.', '2005-07-01 19:00:57.000000', NULL, 1),
(1498149, 196347, 24212, '<td valign="top">I love the way that that cow appears to be looking at the camera and asking if her pose is OK. The lines are bold and the colours wonderful.</td>', 'I love the way that that cow appears to be looking at the camera and asking if her pose is OK. The lines are bold and the colours wonderful.', '2005-07-01 19:02:20.000000', NULL, 1),
