(1498183, 196211, 39410, '<td valign="top">I really like the way the cross almost glows against the dark trees.</td>', 'I really like the way the cross almost glows against the dark trees.', '2005-07-01 19:16:58.000000', NULL, 1),
(1498185, 193891, 24212, '<td valign="top">I think that, rather than ruining things, the lens flare gives this a real kick. I like the composition. The lines really lead the eye in.</td>', 'I think that, rather than ruining things, the lens flare gives this a real kick. I like the composition. The lines really lead the eye in.', '2005-07-01 19:17:53.000000', NULL, 1),
(1498188, 195839, 24212, '<td valign="top">A lovely, clean shot and the colouration of the sky is great.</td>', 'A lovely, clean shot and the colouration of the sky is great.', '2005-07-01 19:18:36.000000', NULL, 1),
