(1498668, 196304, 4793, '<td valign="top">Beautiful, is this a home? Nice shot</td>', 'Beautiful, is this a home? Nice shot', '2005-07-02 00:04:24.000000', NULL, 1),
(1498670, 196370, 4793, '<td valign="top">Nice industrial shot</td>', 'Nice industrial shot', '2005-07-02 00:05:02.000000', NULL, 1),
(1498671, 195096, 4793, '<td valign="top">Cute kids, nice shot</td>', 'Cute kids, nice shot', '2005-07-02 00:05:31.000000', NULL, 1),
(1498674, 196372, 4793, '<td valign="top">Different, nice shot</td>', 'Different, nice shot', '2005-07-02 00:06:40.000000', NULL, 1),
(1498675, 193891, 4793, '<td valign="top">Nice</td>', 'Nice', '2005-07-02 00:07:08.000000', NULL, 1),
(1498677, 195910, 4793, '<td valign="top">Nice shot</td>', 'Nice shot', '2005-07-02 00:07:35.000000', NULL, 1),
